   if(!live.current||ticket!==action.current)return;
   if(fileKind==='pdf'&&(!pdf.type.toLowerCase().startsWith('application/pdf')||await pdf.slice(0,5).text()!=='%PDF-'))throw new Error('Le service n’a pas renvoyé un PDF valide. Votre brouillon est conservé.');
